Lemma novalign_clip : forall dx sx DX SX, - 2^16 <= dx <= 2^16 -> - 2^16 <= sx <= 2^16 -> rop_novalign dx sx ->
  DX = Z.max dx 0 - Z.min (sx - Z.min dx 0) 0 -> SX = Z.max (sx - Z.min dx 0) 0 ->
